 const cooperativeInviteUrl = coop?.inviteCode ? (process.env.NEXT_PUBLIC_APP_URL || (typeof window !== "undefined" ? window.location.origin : "")) + "/cooperative-invite/" + encodeURIComponent(coop.inviteCode) : "";
